    const char *aclConfigPath  = "../src/acl.json";
    return aclInit(aclConfigPath);
  }
};
// 全局变量构造
ResourceManager g_resource_manager;
int main() {
  // 初始化
  aclError ret = g_resource_manager.Init();
  // 业务处理代码
  // 没有显式去初始化，最后 ResourceManager 全局变量析构时调用 aclFinalize
  // 由于全局变量析构是在 main函数退出后才执行，全局变量析构和进程依赖 so的卸载顺序无法控制
  // 会出现 aclFinalize 访问的一些资源所在 so已经被卸载，从而导致进程退出异常
  return 0;
}
5.3 模型推理问题
5.3.1 使用dump功能未获取 dump结果
问题现象描述
日志显示正确执行了 Dump功能，但在 Dump结果路径下没有 Dump的结果。日志信息
包含了以下关键字：
[INFO] ASCENDCL ****** "HandleDumpConfig  end in HandleDumpConfig."
[INFO] ASCENDCL ****** "set HandleDumpConfig  success in aclInit"
可能原因
分析上述日志信息，可能存在以下故障原因： Dump配置的模型名与实际的模型名不匹
配。
处理步骤
针对分析的故障可能原因，可以参考下面步骤处理：
检查Dump配置文件 acl.json，确保 Dump配置文件合法，例如 model_name 是否配置
正确。示例如下：
{
    "dump":{
        "dump_list":[
             {
                "model_name":"ResNet-50",
                  "layer":[
                             "conv1conv1_relu"
                          ]
             },
             {
                "model_name":"mxnet-model"
             }
        ],
        "dump_mode":"output",
        "dump_path":"/home/test/output/dump"
    }
}
通过ATC命令生成模型的 json文件，在 json文件中查找“ name”字段对应值，查找模
型名称和算子名称，模型名称在 "graph"字段外、算子名称在 "graph"字段内。CANN社区版
