解决方法
优化应用代码逻辑，复用输出图片描述类型 acldvppPicDesc 时，在下一次解码前需重
新设置输出图片 format、width、height、widthStride 、heightStride 。
正例代码片段：
aclError ret;
int restLen = 10;
uint32_t inBufferSize  = 0;
void *g_picOutBufferDev;
void *inBufferDev  = nullptr;
acldvppPicDesc *picOutputDesc;
size_t dataSize = (INPUT_WIDTH * INPUT_HEIGHT * 3) / 2;
// 申请一个 picOutputDesc, 每帧复用
picOutputDesc = acldvppCreatePicDesc();
// read file to device memory
ReadFileToDeviceMem(filePath.c_str(),  inBufferDev,  inBufferSize);
while (restLen > 0) {
        // 等待前一个使用 picOutputDesc 解码帧结束，重新复用 picOutputDesc, 并针对这一帧重新设置 Format、
width、height、widthStride 、heightStride 参数值
        ret = acldvppSetPicDescFormat(picOutputDesc, static_cast<acldvppPixelFormat>(1)); // 1 ：YUV420 
semi-planner （nv12）
        ret = acldvppSetPicDescWidth(picOutputDesc, 1920);
        ret = acldvppSetPicDescHeight(picOutputDesc, 1080);
        ret = acldvppSetPicDescWidthStride(picOutputDesc, 1920);
        ret = acldvppSetPicDescHeightStride(picOutputDesc, 1080);
        ret = acldvppMalloc(&g_picOutBufferDev,  dataSize);
        ret = acldvppSetPicDescData(picOutputDesc, g_picOutBufferDev);
        ret = acldvppSetPicDescSize(picOutputDesc, dataSize);
        ret = aclvdecSendFrame(vdecChannelDesc, streamInputDesc, picOutputDesc, nullptr, nullptr);
        restLen = restLen - 1;
}
反例代码片段：
aclError ret;
int restLen = 10;
uint32_t inBufferSize  = 0;
void *g_picOutBufferDev;
void *inBufferDev  = nullptr;
acldvppPicDesc *picOutputDesc;
size_t dataSize = (INPUT_WIDTH * INPUT_HEIGHT * 3) / 2;
// 申请一个 picOutputDesc ，每帧复用，且对 Format、width、height、widthStride 、heightStride 参数值只设置
了一次
picOutputDesc = acldvppCreatePicDesc();
ret = acldvppSetPicDescFormat(picOutputDesc, static_cast<acldvppPixelFormat>(1)); // 1 ：YUV420 semi-
planner（nv12）
ret = acldvppSetPicDescWidth(picOutputDesc, 1920);
ret = acldvppSetPicDescHeight(picOutputDesc, 1080);
ret = acldvppSetPicDescWidthStride(picOutputDesc, 1920);
ret = acldvppSetPicDescHeightStride(picOutputDesc, 1080);
// read file to device memory
ReadFileToDeviceMem(filePath.c_str(),  inBufferDev,  inBufferSize);
while (restLen > 0) {
        // 等待前一个使用 picOutputDesc 解码帧结束，重新复用 picOutputDesc, 但没有重新设置 Format、width、
height、widthStride 、heightStride 参数值
    // 如果前一帧解码失败， picOutputDesc_ 的参数 Format、width、height、widthStride 、heightStride 变成默
认值0，
    // width 、height、widthStride 、heightStride 为0时，vdec会以实际图片宽高解码输出，但 Format为0，表示
YUV400格式， vdec不支持解码输出该格式，会导致本帧参数不合法解码失败
        ret = acldvppMalloc(&g_picOutBufferDev,  dataSize);
        ret = acldvppSetPicDescData(picOutputDesc, g_picOutBufferDev);
        ret = acldvppSetPicDescSize(picOutputDesc, dataSize);
        ret = aclvdecSendFrame(vdecChannelDesc, streamInputDesc, picOutputDesc, nullptr, nullptr);
        restLen = restLen - 1;
